do $$declare m public.unit_material_versions%rowtype; issues jsonb;begin for m in select * from public.unit_material_versions where id in ('25308485-debf-5d99-8b21-7e647d1263fb','2153fc5a-a0a2-532e-a4b3-a64f3368873d','88bf8bd3-4f9f-58c0-b6f7-0b97398226c3','c6576acc-b045-58f0-bb63-c0f386a0b82c','c6778f4b-9a8c-5509-8d1f-10f6c0f2f43d','4c623c85-0bc9-59d1-a658-e37f56cd8997','655f8fa1-ebeb-5ee2-93f6-beb1fee5cf9e','6ace69f7-a9bb-5d00-ae5a-652eca763086','d1b46c81-808d-57de-bc6c-25cc19b6cb96','86355072-adf3-52d3-a85d-df48e6af2b4e') loop issues:=private.unit_material_issues(m);if issues<>'[]'::jsonb then raise exception 'material_stage_qa_failed: % %',m.material_key,issues;end if;update public.unit_material_versions set qa=jsonb_build_object('passed',true,'issues',issues,'fingerprint',m.fingerprint,'checkedAt',clock_timestamp(),'checkVersion','unit-material-qa-v1','actorKind','automated-onboarding') where id=m.id;insert into public.unit_material_events(material_version_id,event,detail) select id,'qa',qa from public.unit_material_versions where id=m.id;end loop;end$$;
